<?php
if (!defined('ABSPATH')) { exit; }
global $wpdb; $products=SPF_Database::table('products'); $lots=SPF_Database::table('lots'); $product_rows=$wpdb->get_results("SELECT id,name,barcode FROM $products WHERE status='active' ORDER BY name ASC LIMIT 500",ARRAY_A); $lot_rows=$wpdb->get_results("SELECT l.*, p.name FROM $lots l INNER JOIN $products p ON p.id=l.product_id WHERE p.status='active' ORDER BY l.id DESC LIMIT 100",ARRAY_A);
?>
<div class="wrap spf-wrap"><h1><?php esc_html_e('Inventario / Lotes','sistema-para-farmacias'); ?></h1><div class="spf-panel"><h2><?php esc_html_e('Entrada de lote','sistema-para-farmacias'); ?></h2><form id="spf-lot-form" class="spf-grid-form"><input type="hidden" name="action" value="spf_add_lot"><input type="hidden" name="nonce" value="<?php echo esc_attr(wp_create_nonce('spf_nonce')); ?>"><label><?php esc_html_e('Producto','sistema-para-farmacias'); ?><select name="product_id" required><option value=""><?php esc_html_e('Seleccionar','sistema-para-farmacias'); ?></option><?php foreach($product_rows as $product): ?><option value="<?php echo esc_attr($product['id']); ?>"><?php echo esc_html($product['name'].($product['barcode']?' · '.$product['barcode']:'')); ?></option><?php endforeach; ?></select></label><div><button class="button" id="spf-scan-inventory-product" type="button"><?php esc_html_e('Escanear producto','sistema-para-farmacias'); ?></button></div><label><?php esc_html_e('Lote','sistema-para-farmacias'); ?><input name="lot_number" type="text"></label><label><?php esc_html_e('Vencimiento','sistema-para-farmacias'); ?><input name="expiry_date" type="date"></label><label><?php esc_html_e('Cantidad','sistema-para-farmacias'); ?><input name="quantity" type="number" min="1" required></label><label><?php esc_html_e('Precio compra','sistema-para-farmacias'); ?><input name="purchase_price" type="number" step="0.01" min="0"></label><label><?php esc_html_e('Proveedor','sistema-para-farmacias'); ?><input name="supplier" type="text"></label><button class="button button-primary" type="submit"><?php esc_html_e('Añadir lote','sistema-para-farmacias'); ?></button></form><div id="spf-lot-result"></div><div id="spf-scanner" class="spf-scanner" style="display:none;"><video id="spf-video" playsinline></video><p id="spf-scanner-status" class="spf-scanner-status"><?php esc_html_e('Apunta al código de barras.','sistema-para-farmacias'); ?></p><button id="spf-stop-scan" class="button" type="button"><?php esc_html_e('Cerrar cámara','sistema-para-farmacias'); ?></button></div></div><div class="spf-panel"><h2><?php esc_html_e('Últimos lotes / stock actual','sistema-para-farmacias'); ?></h2><div class="spf-table-scroll"><table class="widefat striped"><thead><tr><th>ID</th><th><?php esc_html_e('Producto','sistema-para-farmacias'); ?></th><th><?php esc_html_e('Lote','sistema-para-farmacias'); ?></th><th><?php esc_html_e('Vencimiento','sistema-para-farmacias'); ?></th><th><?php esc_html_e('Cantidad disponible','sistema-para-farmacias'); ?></th><th><?php esc_html_e('Precio compra','sistema-para-farmacias'); ?></th><th><?php esc_html_e('Proveedor','sistema-para-farmacias'); ?></th></tr></thead><tbody><?php foreach($lot_rows as $row): ?><tr><td><?php echo esc_html($row['id']); ?></td><td><strong><?php echo esc_html($row['name']); ?></strong></td><td><?php echo esc_html($row['lot_number']); ?></td><td><?php echo esc_html($row['expiry_date']); ?></td><td><?php echo esc_html((int)$row['quantity']); ?></td><td><?php echo esc_html(SPF_Config::money($row['purchase_price'])); ?></td><td><?php echo esc_html($row['supplier']); ?></td></tr><?php endforeach; ?></tbody></table></div></div></div>
